$ErrorActionPreference='Stop';$root=$PSScriptRoot
Import-Module (Join-Path $root 'src/VerticalSlice.psm1') -Force -DisableNameChecking
$cases=@(
 @{text='look around the room'},@{text='misty step to the desk'},@{text='cast Eldritch Blast against the wall'},@{text='look at the desk'},@{text='read the receipts'},@{text='inspect correspondence'},@{text='look at the rug'},@{text='investigate the dark mark';roll=11},@{text='investigate the stain';roll=20},@{text='carefully investigate the dark mark';roll=16},@{text='look at the fireplace'},@{text='investigate the scorch marks';roll=11},@{text='investigate the burn marks';roll=20},@{text='use Detect Magic on the fireplace'},@{text='look at the painting'},
