function Categories($v){$c=[Collections.Generic.List[string]]::new();foreach($e in @($v.GroundingErrors)){if($e-match'unsupported physical'){$c.Add('unsupported_physical_object')}elseif($e-match'known context'){$c.Add('known_fact_repetition')}elseif($e-match'premature'){$c.Add('premature_interpretation')}elseif($e-match'continuity'){$c.Add('continuity_error')}elseif($e-match'knowledge|belief'){$c.Add('agency_violation')}elseif($e-match'contradict|safe|door'){$c.Add('state_contradiction')}else{$c.Add('other')}};if(-not$v.Lexical.Passed){$c.Add('other')};if($v.Structural.AgencyRiskHits.Count-or$v.Structural.FirstPersonHits.Count){$c.Add('agency_violation')};if(-not$v.Structural.HasSecondPerson-or$v.Structural.ThirdPersonActorDrift){$c.Add('tense_person')};if($v.Structural.DatasetFormHits.Count){$c.Add('termination')};@($c|Select-Object -Unique)}
$rawPath=Join-Path $root 'eval/narration_playability_diagnostic_raw.jsonl';if(Test-Path $rawPath){Remove-Item $rawPath};$session=New-CallumStudySession $root;$rows=@();$counts=[ordered]@{};$rollCounts=[ordered]@{}
for($i=0;$i-lt$cases.Count;$i++){$case=$cases[$i];if($case.reset){$session=New-CallumStudySession $root};$watch=[Diagnostics.Stopwatch]::StartNew();$interpret=Invoke-SliceInterpretation $session $case.text -Seed (41000+$i);if($interpret.Status-ne'RESOLVED'){throw "Diagnostic input did not resolve: $($case.text)"};$fixed=if($case.ContainsKey('roll')){[Nullable[int]]$case.roll}else{[Nullable[int]]$null};$resolution=Resolve-SliceIntent $session $interpret.Intent $fixed;if(-not$resolution.Accepted){throw "Diagnostic engine rejected: $($case.text): $($resolution.Reason)"};$narration=Invoke-SliceNarration $session $resolution $null 2 $root;$watch.Stop();$attempts=@();for($j=0;$j-lt$narration.RawOutputs.Count;$j++){$v=$narration.Validations[$j];$cats=@(Categories $v);foreach($cat in $cats){if(-not$counts.Contains($cat)){$counts[$cat]=0};$counts[$cat]++};$attempts+=[pscustomobject]@{attempt=($j+1);raw=$narration.RawOutputs[$j];passed=$v.Passed;validators_fired=$cats;validation=$v}};$indicator=Format-SliceRollFeedback $resolution.Check standard;if($resolution.Check){$outcome=$resolution.Check.Outcome;if(-not$rollCounts.Contains($outcome)){$rollCounts[$outcome]=0};$rollCounts[$outcome]++};$row=[ordered]@{turn=($i+1);player_input=$case.text;engine_result=[ordered]@{classification=$resolution.Classification;degree=$resolution.Degree;events=@($resolution.Events);active_check=$resolution.Check;roll_indicator=$indicator};new_this_turn=@($resolution.Handoff.NewThisTurn);known_context=@($resolution.Handoff.KnownContext);attempts=$attempts;retry_count=($narration.RawOutputs.Count-1);fallback_used=$narration.FallbackUsed;displayed_output=$narration.Text;output_words=@([regex]::Matches($narration.Text,"\b[\p{L}\p{N}'’-]+\b")).Count;prompt_characters=$narration.PromptCharacters;prompt_bytes=$narration.PromptBytes;latency_seconds=[math]::Round($watch.Elapsed.TotalSeconds,4)};$rows+=[pscustomobject]$row;$row|ConvertTo-Json -Depth 18 -Compress|Add-Content -Encoding utf8 $rawPath;Write-Host "Narration diagnostic $($i+1)/30: $($case.text)"}
$lat=@($rows.latency_seconds|Sort-Object);$first=@($rows|Where-Object{$_.retry_count-eq0}).Count;$fallback=@($rows|Where-Object{$_.fallback_used}).Count;$summary=[ordered]@{generated_utc=[datetime]::UtcNow.ToString('o');turns=$rows.Count;meaningful=@($rows|Where-Object{$_.engine_result.classification-eq'MEANINGFUL'}).Count;mundane=@($rows|Where-Object{$_.engine_result.classification-eq'MUNDANE'}).Count;first_pass=$first;retries=($rows.Count-$first);fallbacks=$fallback;first_pass_percent=[math]::Round(100*$first/$rows.Count,1);retry_percent=[math]::Round(100*($rows.Count-$first)/$rows.Count,1);fallback_percent=[math]::Round(100*$fallback/$rows.Count,1);validator_failure_categories=$counts;roll_indicators=$rollCounts;average_latency_seconds=[math]::Round((($lat|Measure-Object -Average).Average),4);median_latency_seconds=[math]::Round([double]$lat[[math]::Floor(($lat.Count-1)/2)],4);maximum_latency_seconds=[math]::Round((($lat|Measure-Object -Maximum).Maximum),4);average_prompt_characters=[math]::Round((($rows.prompt_characters|Measure-Object -Average).Average),1);average_output_words=[math]::Round((($rows.output_words|Measure-Object -Average).Average),1)};$summary|ConvertTo-Json -Depth 10|Set-Content -Encoding utf8 (Join-Path $root 'eval/narration_playability_diagnostic_summary.json');$summary|ConvertTo-Json -Depth 10
